def AlphaNum_NumAlpha(s):
    alphabet = ['a', 'b', 'c', 'd', 'e', 'f', 'g', 'h', 'i', 'j', 'k', 'l', 'm', 'n', 'o', 'p', 'q', 'r', 's', 't', 'u', 'v', 'w', 'x', 'y', 'z']
    alphabetnums = {letter: str(index + 1) for index, letter in enumerate(alphabet)}
    numalphabet = {str(index + 1): letter for index, letter in enumerate(alphabet)}
    result = []
    i = 0
    while i < len(s):
        if s[i].isdigit():
            num = s[i]
            result.append(numanphabet[num])
            i += 1
        else:
            result.append(alphabetnums[s[i]])
            i += 1
    return ''.join(result)
